<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=1365, initial-scale=1">
<meta name="sunny-upstream-hash" content="cc53e27067e7bc8a665907e6eb59b11ca421d10dad73430b8c4678caf2d6da08">
<title>Lantern Festival: The Night You Light</title>
<style>
/* ---------- base ---------- */
*{box-sizing:border-box}
html,body{margin:0;padding:0;height:100%;background:#04050d;overflow:hidden;
  font-family:"Trebuchet MS","Segoe UI",Verdana,sans-serif;-webkit-font-smoothing:antialiased}
#stage{position:absolute;width:1365px;height:768px;transform-origin:top left;overflow:hidden;
  background:
   radial-gradient(900px 420px at 50% 108%, #2a1a3d 0%, rgba(0,0,0,0) 70%),
   radial-gradient(700px 380px at 12% -10%, #16244f 0%, rgba(0,0,0,0) 70%),
   linear-gradient(#070a20 0%, #0d1130 45%, #171233 100%);
  color:#f6ecd8;user-select:none;touch-action:none}
body.rain #stage{background:
   radial-gradient(900px 420px at 50% 108%, #16303f 0%, rgba(0,0,0,0) 70%),
   radial-gradient(700px 380px at 12% -10%, #0f2b48 0%, rgba(0,0,0,0) 70%),
   linear-gradient(#050c1c 0%, #0a1a33 45%, #0d2036 100%)}
body.snow #stage{background:
   radial-gradient(900px 420px at 50% 108%, #33355c 0%, rgba(0,0,0,0) 70%),
   radial-gradient(700px 380px at 12% -10%, #263257 0%, rgba(0,0,0,0) 70%),
   linear-gradient(#0a0d24 0%, #141a3f 45%, #202a52 100%)}
:root{
 --gold:#ffc65c; --gold2:#ffe6a8; --amber:#e8913a; --persimmon:#ff7a45;
 --teal:#4fd1c5; --dark:#0a0d24; --panel:rgba(255,255,255,.07);
}

/* ---------- ambience ---------- */
.floatLantern{position:absolute;width:12px;height:15px;border-radius:5px;
 background:radial-gradient(circle at 40% 30%,#fff2c9,#ffb347);opacity:.45;
 box-shadow:0 0 12px rgba(255,190,90,.7);animation:rise linear infinite}
@keyframes rise{from{transform:translateY(0) translateX(0)}to{transform:translateY(-900px) translateX(40px)}}

/* ---------- canopy ---------- */
#canopy{position:absolute;left:0;top:0;width:1365px;height:100px}
#canopy svg{position:absolute;left:0;top:0}
#titleBar{position:absolute;right:14px;top:8px;text-align:right;font-size:13px;color:#9aa6d0;letter-spacing:.4px}
#titleBar b{display:block;font-size:16px;color:var(--gold2);letter-spacing:1px}
#recBtn{position:absolute;right:14px;top:60px;font-size:11px;background:rgba(255,255,255,.08);
 border:1px solid rgba(255,255,255,.18);color:#c9d2ef;border-radius:20px;padding:4px 12px;cursor:pointer}
#recBtn:hover{background:rgba(255,255,255,.16)}
.arcLabel{font-size:11px;fill:#8b96c4}

/* ---------- ribbon ---------- */
#ribbon{position:absolute;left:0;top:96px;width:1365px;height:82px;padding:8px 30px 0 30px;text-align:center}
#stationTag{font-size:13px;letter-spacing:2.4px;color:var(--teal);text-transform:uppercase}
#promptText{font-size:21px;line-height:1.3;margin-top:5px;color:#fdf3e0;max-width:1180px;margin-left:auto;margin-right:auto}
#promptText b{color:var(--gold)}
#howLine{font-size:14px;color:#a9b3dc;margin-top:3px}

/* ---------- world ---------- */
#world{position:absolute;left:0;top:178px;width:1365px;height:318px}
.scene{position:absolute;inset:0}
.wobble{animation:wob .55s ease-in-out 2}
@keyframes wob{0%,100%{transform:translateX(0)}25%{transform:translateX(-9px) rotate(-.6deg)}75%{transform:translateX(9px) rotate(.6deg)}}
.avalanche{animation:aval 1.1s ease-in}
@keyframes aval{0%{transform:none}30%{transform:translateY(10px) rotate(1.5deg)}100%{transform:translateY(210px) rotate(-7deg);opacity:.15}}

/* generic pieces */
.helper{position:relative;width:78px;display:inline-block;text-align:center;vertical-align:bottom}
.helper .head{width:26px;height:26px;border-radius:50%;background:#2b3566;margin:0 auto;border:2px solid #46538f}
.helper .body{width:44px;height:56px;border-radius:16px 16px 8px 8px;background:#242e5c;margin:2px auto 0;border:2px solid #46538f}
.helper.hi .head,.helper.hi .body{background:#5b4a2a;border-color:var(--gold);box-shadow:0 0 16px rgba(255,198,92,.6)}
.armful{display:flex;justify-content:center;gap:3px;margin-bottom:4px;padding:3px;border-radius:8px}
.armful.hi{background:rgba(255,198,92,.16);outline:2px solid var(--gold)}
.lan{width:14px;height:18px;border-radius:6px;background:linear-gradient(#ffe7ae,#ffab3f);
 box-shadow:0 0 8px rgba(255,180,80,.75);display:inline-block}
.lan.dim{background:linear-gradient(#4a4a63,#31314a);box-shadow:none}
.lan.amberL{background:linear-gradient(#ffd9a0,#e07f24)}
.flag{width:0;height:0;border-left:13px solid var(--persimmon);border-top:6px solid transparent;
 border-bottom:6px solid transparent;display:inline-block;margin:2px 3px 2px 0;filter:drop-shadow(0 0 4px rgba(255,122,69,.6))}
.ban{width:11px;height:22px;background:linear-gradient(#7ae7dc,#2aa79a);display:inline-block;margin:1px;
 border-radius:2px 2px 5px 5px;box-shadow:0 0 5px rgba(79,209,197,.5)}
.cup{width:12px;height:14px;background:linear-gradient(#fff0c2,#ffcf6b);display:inline-block;margin:1.5px;
 border-radius:2px 2px 6px 6px}
.badge{width:13px;height:13px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#ffb03a);
 display:inline-block;margin:2px;box-shadow:0 0 5px rgba(255,176,58,.6)}
.bead{width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#c7fff6,#3fb6ab);
 display:inline-block;margin:1.5px}
.kid{width:11px;height:16px;border-radius:6px 6px 3px 3px;background:#8ea2ff;display:inline-block;margin:1.5px}
.lightDot{width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff6d6,#ffc65c);
 display:inline-block;margin:4px;box-shadow:0 0 10px rgba(255,198,92,.8)}
.lightDot.off{background:#2c3157;box-shadow:none}
.lightDot.bad{background:radial-gradient(circle at 35% 30%,#ffd0c0,#e35b3b);box-shadow:0 0 10px rgba(227,91,59,.7)}

.crateBox{border:3px solid #6f7bb5;border-radius:10px;background:rgba(20,26,60,.6);padding:8px 10px;display:inline-block}
.fixedBin{border:3px solid var(--gold);border-radius:12px;background:rgba(60,44,16,.55);padding:8px 12px;position:relative}
.fixedBin.flash{animation:binflash .6s ease 3}
@keyframes binflash{0%,100%{box-shadow:0 0 0 rgba(255,198,92,0)}50%{box-shadow:0 0 28px 6px rgba(255,198,92,.85)}}
.binNote{position:absolute;top:-24px;left:50%;transform:translateX(-50%);font-size:13px;color:var(--gold);white-space:nowrap}
.sect{display:inline-block;border:2px dashed #55609c;border-radius:8px;padding:4px 4px 2px;margin:3px;background:rgba(255,255,255,.03)}
.rowRig{display:flex;flex-wrap:wrap;align-items:center;border-bottom:2px solid #3b4477;padding:2px 0;min-height:26px}
.readout{position:absolute;left:50%;transform:translateX(-50%);bottom:4px;font-size:19px;color:#dfe6ff;
 background:rgba(8,10,30,.7);padding:5px 16px;border-radius:20px;border:1px solid rgba(255,255,255,.14)}
.readout .good{color:#7cf0a8}.readout .bad{color:#ff9a7a}
.panelBox{position:absolute;border:2px solid rgba(255,255,255,.14);border-radius:14px;background:rgba(10,14,38,.55);padding:10px}
.panelBox.active{border-color:var(--gold);box-shadow:0 0 22px rgba(255,198,92,.28)}
.panelTitle{font-size:13px;letter-spacing:1.5px;color:var(--teal);text-transform:uppercase;margin-bottom:6px}

/* tags (beat 1) */
.tag{position:absolute;cursor:pointer;background:linear-gradient(180deg,rgba(255,225,170,.96),rgba(255,183,86,.92));
 color:#3a2508;border-radius:14px;padding:8px 14px;box-shadow:0 6px 20px rgba(255,170,60,.35);
 border:2px solid #ffe9bd;max-width:230px;text-align:center;animation:bob 3s ease-in-out infinite}
.tag .num{font-size:30px;font-weight:bold;line-height:1}
.tag .sub{font-size:12.5px;line-height:1.15;margin-top:2px}
.tag:hover{transform:scale(1.06)}
.tag.wrongTag{animation:shake .4s}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-8px)}75%{transform:translateX(8px)}}
@keyframes bob{0%,100%{margin-top:0}50%{margin-top:-6px}}
.tag.pulseHalo{box-shadow:0 0 0 0 rgba(255,220,140,.9);animation:halo 1.5s ease-out infinite}
@keyframes halo{0%{box-shadow:0 0 0 0 rgba(255,220,140,.75)}100%{box-shadow:0 0 0 26px rgba(255,220,140,0)}}

/* ---------- slot frame ---------- */
#slots{position:absolute;left:0;top:500px;width:1365px;height:128px;display:flex;justify-content:center;
 align-items:center;gap:20px}
.slot{width:300px;height:110px;border-radius:16px;position:relative;cursor:default;
 background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.02));
 border:2px solid rgba(255,255,255,.16);display:flex;flex-direction:column;align-items:center;justify-content:center}
.slot .sName{font-size:13px;letter-spacing:2px;color:#b9c3ea}
.slot .sSub{font-size:12.5px;color:#8f9ac6;margin-top:1px;text-align:center;padding:0 8px}
.slot .sVal{font-size:34px;font-weight:bold;margin-top:2px;color:#5c6699}
.slot.dark{border-color:#39406f;background:radial-gradient(circle at 50% 60%,rgba(0,0,0,.55),rgba(255,255,255,.03));
 animation:breathe 2s ease-in-out infinite}
@keyframes breathe{0%,100%{box-shadow:inset 0 0 18px rgba(0,0,0,.8)}50%{box-shadow:inset 0 0 34px rgba(80,90,160,.55)}}
.slot.droppable{cursor:pointer}
.slot.hover{border-color:var(--gold);box-shadow:0 0 24px rgba(255,198,92,.4)}
.slot.known{border-color:rgba(255,198,92,.55)}
.slot.known .sVal{color:var(--gold)}
.slot.named{border-color:var(--gold);box-shadow:0 0 30px rgba(255,198,92,.45)}
.slot.named .sVal{color:var(--gold2)}
.slot.live .sVal{color:var(--gold2);text-shadow:0 0 16px rgba(255,220,140,.8)}
.slot.rejected{animation:shake .4s}
.slotIcon{position:absolute;top:-13px;left:14px;font-size:11px;letter-spacing:1px;color:#0c1030;
 background:var(--teal);border-radius:9px;padding:2px 9px}
.slot.frameIgnite{animation:ign .6s ease-out}
@keyframes ign{0%{box-shadow:0 0 0 rgba(255,220,140,0)}40%{box-shadow:0 0 44px 10px rgba(255,220,140,.75)}100%{box-shadow:0 0 0 rgba(255,220,140,0)}}

/* ---------- controls ---------- */
#controls{position:absolute;left:0;top:630px;width:1365px;height:138px;display:flex;align-items:center;
 justify-content:center;gap:22px;padding:0 24px}
#dock{width:210px;display:flex;flex-direction:column;align-items:center;gap:6px}
#qlantern{width:62px;height:76px;border-radius:22px 22px 14px 14px;cursor:grab;position:relative;
 background:radial-gradient(circle at 40% 32%,#fff6d0,#ffb43f);
 box-shadow:0 0 26px rgba(255,180,80,.85);display:flex;align-items:center;justify-content:center;
 font-size:38px;font-weight:bold;color:#5a3606;touch-action:none}
#qlantern.dragging{cursor:grabbing;position:absolute;z-index:60;pointer-events:none}
#qlantern.hidden{display:none}
#dockHint{font-size:12.5px;color:#a9b3dc;text-align:center;line-height:1.25}
#dialWrap{flex:1;max-width:640px;display:flex;flex-direction:column;align-items:center;gap:6px}
#dialRow{display:flex;align-items:center;gap:14px;width:100%}
.stepBtn{width:64px;height:58px;border-radius:14px;font-size:30px;line-height:1;border:2px solid rgba(255,255,255,.22);
 background:rgba(255,255,255,.08);color:#f2e9d5;cursor:pointer}
.stepBtn:hover{background:rgba(255,255,255,.17)}
#dialVal{min-width:104px;text-align:center;font-size:46px;font-weight:bold;color:var(--gold2);
 text-shadow:0 0 18px rgba(255,200,110,.6)}
#slider{flex:1;-webkit-appearance:none;height:14px;border-radius:10px;background:linear-gradient(90deg,#2b3164,#4a5390);outline:none}
#slider::-webkit-slider-thumb{-webkit-appearance:none;width:40px;height:40px;border-radius:50%;cursor:pointer;
 background:radial-gradient(circle at 38% 30%,#fff3cf,#ffb03a);border:3px solid #fff0c6;box-shadow:0 0 16px rgba(255,180,80,.9)}
#slider::-moz-range-thumb{width:40px;height:40px;border-radius:50%;cursor:pointer;
 background:radial-gradient(circle at 38% 30%,#fff3cf,#ffb03a);border:3px solid #fff0c6}
#dialLabel{font-size:13.5px;color:#a9b3dc}
#dialWrap.locked{opacity:.42}
#dialWrap.locked #slider,#dialWrap.locked .stepBtn{pointer-events:none}
#runBtn{min-width:180px;height:70px;border-radius:18px;font-size:22px;font-weight:bold;cursor:pointer;
 border:3px solid #ffe6ae;color:#3a2405;background:linear-gradient(180deg,#ffe3ab,#ffb545);
 box-shadow:0 8px 26px rgba(255,170,60,.35)}
#runBtn:hover{filter:brightness(1.08)}
#runBtn.ghost{background:rgba(255,255,255,.09);color:#dfe6ff;border-color:rgba(255,255,255,.24);box-shadow:none}
#runBtn:disabled{opacity:.35;cursor:not-allowed}
#helpWrap{width:212px;display:flex;flex-direction:column;align-items:center;gap:6px}
#helpBtn{width:196px;height:56px;border-radius:16px;font-size:15px;cursor:pointer;color:#eaf2ff;
 background:rgba(79,209,197,.16);border:2px solid rgba(79,209,197,.55)}
#helpBtn:hover{background:rgba(79,209,197,.3)}
#helpBtn:disabled{opacity:.32;cursor:not-allowed}
#helpNote{font-size:11.5px;color:#8f9ac6;text-align:center;line-height:1.2}
